function CellSelection({
  caption = "{{caption}}",
  accent = "{{accent}}",
  mode = "{{mode}}",
  showRef = {{showRef}},
}) {
  const cellStyle = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  const blockStyle = {
    ...cellStyle,
    position: "relative",
    background: mode === "row" || mode === "block" ? "#A8E6C155" : "transparent",
    outline: mode === "block" ? `1px solid ${accent}` : mode === "single" ? `2px solid ${accent}` : "none",
    outlineOffset: -2,
  };
  const rowStyle = { background: mode === "row" ? "#A8E6C155" : "transparent" };
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              {["Order", "Customer", "Status", "Total"].map((h) => <th key={h} scope="col" style={cellStyle}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            <tr><td style={cellStyle}>#1042</td><td style={cellStyle}>A. Whitfield</td><td style={cellStyle}>Shipped</td><td style={cellStyle}>£64.00</td></tr>
            <tr style={rowStyle}>
              <td style={cellStyle}>#1041</td><td style={cellStyle}>R. Okafor</td>
              <td style={blockStyle}>Processing{showRef && <span style={{ position: "absolute", top: 2, right: 4, fontSize: 10, fontWeight: 600, color: accent }}>C2</span>}</td>
              <td style={blockStyle}>£128.50</td>
            </tr>
            <tr><td style={cellStyle}>#1040</td><td style={cellStyle}>M. Iqbal</td><td style={cellStyle}>Shipped</td><td style={cellStyle}>£22.00</td></tr>
            <tr><td style={cellStyle}>#1039</td><td style={cellStyle}>S. Novak</td><td style={cellStyle}>Refunded</td><td style={cellStyle}>£40.00</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
